public class Rational {private long m,n;public Rational(long m,long n){this.m=m;this.n=n;}public long numerator(){return m;}public long denominator(){return n;}public Rational add(Rational b){long a=m*b.n+b.m*n,d=n*b.n;m=a;n=d;return this;}public Rational subtract(Rational b){long a=m*b.n-b.m*n,d=n*b.n;m=a;n=d;return this;}public Rational multiply(Rational b){long a=m*b.m,d=n*b.n;m=a;n=d;return this;}public Rational divide(Rational b){long a=m*b.n,d=n*b.m;m=a;n=d;return this;}public static void transform(Rational[]a){Rational[]old=new Rational[a.length];for(int i=0;i<a.length;i++)old[i]=new Rational(a[i].m,a[i].n);for(int i=0;i+1<a.length;i+=2)a[i]=new Rational(old[i].m,old[i].n).add(old[i+1]);}public String toString(){return m+"/"+n;}}
